{
  "title": "The Glass Diver's Rescue",
  "gate_token": "w8Y_MtstYy-YtaPy6OQXcg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city's edge.",
      "visual_description": "A collapsed archway marks the entrance to a crumbling city. Frayed royal banners hang from broken spires. Mara studies a sprawled map while the tin fox sniffs the rubble. The oracle lamp flickers on a stone, casting a single eye of light onto the path ahead.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of hidden dangers.",
      "visual_description": "Inside a roofless hall, the oracle lamp's flame eye widens as it projects a shadow of a towering gate. Mara marks the map with a trembling hand. The glass diver adjusts his helmet, peering through a cracked window.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver scouts through a mirror.",
      "visual_description": "In a dusty chamber, the glass diver presses his face to a full-length mirror. His reflection ripples, then shows a courtyard beyond. The tin fox taps a glass eye against the mirror's edge.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox triggers a trap in the courtyard.",
      "visual_description": "A cobbled courtyard half-sunken with rubble. The tin fox steps on a loose stone; a portcullis crashes behind them. Mara pulls the fox back by its tail. The oracle lamp hisses a warning.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "The team faces a cursed tower's entrance.",
      "visual_description": "A twisted tower leans over a narrow alley. Its door is etched with spiraling runes that glow faintly. The glass diver sees a face in the door's grain. Mara traces the runes with ink-stained fingers.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "The sleeping tax collector is found dozing at the tower base.",
      "visual_description": "In a small alcove, the sleeping tax collector snores with a ledger as a pillow. Stamped papers are stuck to his sleeves. The tin fox nudges his boot, but he doesn't stir.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp deciphers the runes on the door.",
      "visual_description": "The oracle lamp floats close to the rune-carved door. Its flame eye traces the patterns, and the runes shift. Mara scribbles notes. The glass diver readies a shard of mirror.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver enters the tower through a window reflection.",
      "visual_description": "The glass diver holds a shard of mirror to the tower's only window. He steps through the reflection into a dark room. Inside, old royal banners are draped over furniture. He signals the others.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara maps a hidden passage within the tower.",
      "visual_description": "In a circular room, Mara discovers a spiral staircase behind a tapestry. She unrolls a fresh parchment and sketches the route. The tin fox climbs the stairs, its key-wind tail ticking.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "The oracle lamp reveals the location of the escape bridge.",
      "visual_description": "At the top of the tower, the oracle lamp projects a map onto the wall. A glowing line leads to a distant bridge. The glass diver memorizes the path. The sleeping tax collector is carried up by the tin fox.",
      "characters": ["oracle_lamp", "glass_diver", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The team descends into a crypt beneath the tower.",
      "visual_description": "A stone staircase spirals down into a crypt lined with faded murals. The glass diver's helmet reflects a ghostly light. Mara holds the oracle lamp high. The tin fox's eyes glow.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "A magic door blocks the crypt exit.",
      "visual_description": "A massive door with a shifting mosaic surface blocks the way. The tiles rearrange into letters. The oracle lamp reads the word 'TRUTH.' The glass diver steps forward, placing a hand on the door.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping tax collector wakes and accidentally solves the door.",
      "visual_description": "The sleeping tax collector stirs, mumbling tax codes. A stamped paper falls from his sleeve onto the door. The mosaic clicks, and the door swings open. He blinks and goes back to sleep.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "The team emerges into a ruined marketplace.",
      "visual_description": "Collapsed stalls and broken carts litter a wide square. Frightened townspeople huddle in shadows, clutching scraps. The tin fox weaves through the debris. Mara checks her map.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols march through the main avenue.",
      "visual_description": "A column of figures in dented armor marches down a broad street. Their helmets have no faces. The glass diver pulls the team into a doorway. The oracle lamp dims its flame.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver creates a distraction using a mirror.",
      "visual_description": "The glass diver steps into a pool of light and holds a mirror at an angle. A blinding beam shoots down the street, drawing the patrols away. The team slips past into a side alley.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "The escape bridge is sighted, but it's guarded by a magical barrier.",
      "visual_description": "A stone bridge arches over a dry riverbed. A shimmering barrier of light blocks the entrance. The oracle lamp's eye narrows. Mara unfolds her map, looking for another way.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses the bridge as dawn breaks.",
      "visual_description": "The glass diver shatters the barrier by throwing a mirror shard into its center. The team runs across the bridge. Behind them, the ruined city glows in the first light. The sleeping tax collector is carried by the tin fox. They reach the far side safely.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

